import React,{useState} from 'react'; import {createRoot} from 'react-dom/client'; import './styles/app.css';
function Owner(){const [url,setUrl]=useState(localStorage.ownerUrl||''),[token,setToken]=useState(localStorage.ownerToken||''),[data,setData]=useState<any>(),[msg,setMsg]=useState(''); async function call(action:string,payload:any={}){localStorage.ownerUrl=url;localStorage.ownerToken=token; const r=await fetch(`${url.replace(/\/$/,'')}/functions/v1/${action}`,{method:'POST',headers:{'content-type':'application/json',authorization:`Bearer ${token}`},body:JSON.stringify(payload)}); const j=await r.json(); if(!r.ok) throw new Error(j.error||'failed'); return j} async function load(){try{setData(await call('owner-dashboard'));setMsg('')}catch(e:any){setMsg(e.message)}} async function createLicense(){const pharmacy_name=prompt('اسم الصيدلية')||''; const owner_email=prompt('بريد المالك')||''; if(!pharmacy_name||!owner_email)return; try{setMsg(JSON.stringify(await call('owner-control',{operation:'create_license',pharmacy_name,owner_email,owner_name:pharmacy_name,days:365}),null,2)); await load()}catch(e:any){setMsg(e.message)}} async function op(operation:string){const license_key=prompt('License key')||''; if(!license_key)return; try{setMsg(JSON.stringify(await call('owner-control',{operation,license_key}),null,2)); await load()}catch(e:any){setMsg(e.message)}} return <main><h1>لوحة الإدارة المركزية — ALSHIFAA</h1><div className="card formgrid"><input value={url} onChange={e=>setUrl(e.target.value)} placeholder="Supabase URL"/><input type="password" value={token} onChange={e=>setToken(e.target.value)} placeholder="Admin JWT"/><button onClick={load}>تحميل</button><button onClick={createLicense}>إنشاء ترخيص</button><button onClick={()=>op('suspend')}>إيقاف</button><button onClick={()=>op('revoke')}>إلغاء</button><button onClick={()=>op('extend')}>تمديد</button><button onClick={()=>op('unbind_device')}>فك ربط جهاز</button></div>{msg&&<pre className="card">{msg}</pre>}{data&&<><div className="grid cards">{Object.entries(data.stats).map(([k,v])=><div className="card stat"><span>{k}</span><b>{String(v)}</b></div>)}</div><div className="card"><h3>التراخيص القريبة الانتهاء</h3><table><tbody>{data.expiring?.map((l:any)=><tr><td>{l.license_key}</td><td>{l.pharmacy_name}</td><td>{l.expires_at}</td><td>{l.status}</td></tr>)}</tbody></table></div><div className="card"><h3>طلبات التفعيل</h3><table><tbody>{data.requests?.map((r:any)=><tr><td>{r.license_key}</td><td>{r.device_id}</td><td>{r.status}</td></tr>)}</tbody></table></div></>}</main>}
createRoot(document.getElementById('owner-root')!).render(<React.StrictMode><Owner/></React.StrictMode>);
